#include <stdio.h>
#include <setjmp.h>
jmp_buf env;
void handle_error() {
  printf("Error occurred!\n");
  longjmp(env, 1);
}
int main() {
  if (setjmp(env) == 0) {
    printf("Executing normal code...\n");
    // Simulate an error
    handle_error();
    printf("This won't print.\n");
  } else {
    printf("Error handled!\n");
  }
  return 0;
}
